import type { PortfolioPieChartData } from '../../types';

export const PORTFOLIO_PIE_SLICE_DEFAULT_SEQUENCE = [
  '#FDD349',
  '#70C6FF',
  '#C9AF82',
  '#B5B4AF',
] as const;

export const PORTFOLIO_PIE_SLICE_COLORS_BY_CHART_ID: Record<
  PortfolioPieChartData['id'],
  readonly string[]
> = {
  liquidType: ['#FDD349', '#FF8C42', '#70C6FF', '#FFBA8F'],
  innovationPillar: ['#FDD349', '#70C6FF', '#B5B4AF'],
  megabrandFramework: ['#FDD349', '#70C6FF', '#B5B4AF', '#8B7355'],
};

export function getPortfolioPieSliceFallbackColor(
  chartId: PortfolioPieChartData['id'],
  sliceIndex: number,
): string {
  const sequence = PORTFOLIO_PIE_SLICE_COLORS_BY_CHART_ID[chartId];
  return sequence[sliceIndex % sequence.length];
}
